        },
        {
          "source": "netlist",
          "quote": "(net (code \"219\") (name \"VOUTN\") ... (node (ref \"R36\") (pin \"1\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"220\") (name \"VOUTP\") ... (node (ref \"R36\") (pin \"2\")"
        }
